/* Kill-switch service worker.
   The blog used to live at the site root with a Chirpy PWA service worker
   registered at this exact URL. Returning visitors still have that worker
   and its cache. This replacement deletes every cache, unregisters itself,
   and reloads open tabs so they see the new site structure. */
self.addEventListener("install", function () { self.skipWaiting(); });
self.addEventListener("activate", function (e) {
  e.waitUntil(
    caches.keys()
      .then(function (keys) { return Promise.all(keys.map(function (k) { return caches.delete(k); })); })
      .then(function () { return self.registration.unregister(); })
      .then(function () { return self.clients.matchAll({ type: "window" }); })
      .then(function (clients) {
        clients.forEach(function (c) { if (c.navigate) c.navigate(c.url); });
      })
  );
});
